validator:
function validate(input) {
  const [{ Point = [] }] = input;
  const seen = new Set();
  for (const [x] of Point) {
    if (x === null) return 'Every point needs an x.';
    if (seen.has(x)) return `x ${x} appears twice.`;
    seen.add(x);
  }
  if (seen.size < 2) return 'Point needs at least two rows.';
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const count = small ? 2 + Math.floor(rand() * 7) : 1200;
  // Walk right by positive gaps so the points are distinct, then shuffle the rows out of sorted order.
  const maxGap = small ? 5 : 1500;
  let x = Math.floor(rand() * (small ? 21 : 2000001)) - (small ? 10 : 1000000);
  const Point = [];
  for (let i = 0; i < count; i++) {
    Point.push([x]);
    x += 1 + Math.floor(rand() * maxGap);
  }
  for (let i = Point.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [Point[i], Point[j]] = [Point[j], Point[i]];
  }
  return [{ Point }];
}
